    practiceSets: [{ level: "warmup", prompts: [{ prompt: "Rewrite one technical caveat for a coach audience.", answer: "Keep uncertainty meaning and add practical trigger language." }, { prompt: "Create one sentence that appears in both versions.", answer: "Sentence should contain invariant recommendation scope." }] }, { level: "core", prompts: [{ prompt: "Draft analyst and coach versions of a bullpen recommendation.", answer: "Both versions should imply identical role usage boundaries." }, { prompt: "Write three guardrails from one uncertainty statement.", answer: "Include monitor metric, threshold, and review timing." }, { prompt: "Build a cross-version QA checklist.", answer: "Checklist should test recommendation, scope, and caveat alignment." }] }, { level: "stretch", prompts: [{ prompt: "Audit a peer pair for semantic drift.", answer: "Identify mismatches and repair without changing evidence base." }, { prompt: "Design a team style guide for mixed-audience baseball writing.", answer: "Guide should enforce invariance and caveat visibility." }] }],
