    assessmentItems: [{ id: "commb-13-mcq-1", type: "mcq", prompt: "Best report quality signal is:", options: ["Longest methods section", "Traceable claims with inline caveats", "Most charts", "Fewest limitations"], correctAnswer: "Traceable claims with inline caveats", explanation: "Traceability and boundary honesty drive trust." }, { id: "commb-13-exact-1", type: "exact", prompt: "Report architecture aligned to inference order is dependency ____.", correctAnswer: "skeleton", acceptedAnswers: ["dependency skeleton"], explanation: "Skeleton design supports coherent reading." }, { id: "commb-13-exact-2", type: "exact", prompt: "Limitation statement placed next to a claim is an inline ____.", correctAnswer: "caveat", acceptedAnswers: ["inline caveat"], explanation: "Inline caveats improve calibrated interpretation." }]
